-- Consolidated scrutiny rules from the exhaustive word-by-word reading of all 924 human audit
-- queries. 299 per-query rule proposals were collapsed into 31 parameterised rules; adversarial
-- verification rejected 15 of the first 47 drafts, of which 6 were engine defects rather than rule
-- defects (fixed separately in a30a87c6 and 2115406b).
--
-- Every rule below was run through the REAL detection engine over all 109 engagements with Tally
-- data before being written here: 2,427 findings, 22.3 per engagement, 0 handler errors, and no
-- rule silent firm-wide. Per-rule measured volumes are quoted against each entry.
--
-- applicable_to is pinned explicitly on every rule. A NULL would mean "applies to every entity",
-- which is precisely the corporate/non-corporate mixing the split exists to prevent. None of these
-- 31 are bucket-exclusive: the corporate-only rules in this system are the Companies Act tests
-- (CAP-001..007, RPT-*), and nothing in this batch is one.
--
-- Idempotent: re-running updates in place on the rule_id unique key.


-- CAP-201: Capital / partner's / proprietor's account or reserve standing at a debit balance
-- measured: 35 findings across 23 engagements (1.5 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('CAP-201', 'Capital / partner''s / proprietor''s account or reserve standing at a debit balance', 'CAP', 'account',
  '{"check": "expr", "grain": "account", "scope": {"parent_group_keywords": ["capital", "reserve", "partner", "proprietor"], "nonzero": true}, "where": [{"field": "closing", "op": ">", "value": 100000}, {"field": "parent_group", "op": "not_contains", "value": "investment"}, {"field": "parent_group", "op": "not_contains", "value": "payout"}, {"field": "parent_group", "op": "not_contains", "value": "creditor"}, {"field": "parent_group", "op": "not_contains", "value": "loan"}, {"field": "parent_group", "op": "not_contains", "value": "remuneration"}, {"field": "parent_group", "op": "not_contains", "value": "work in"}, {"field": "parent_group", "op": "not_contains", "value": "capital goods"}, {"field": "ledger", "op": "not_contains", "value": "drawing"}, {"field": "ledger", "op": "not_contains", "value": "advance"}, {"field": "ledger", "op": "not_contains", "value": "loan"}, {"field": "ledger", "op": "not_contains", "value": "remuneration"}, {"field": "ledger", "op": "not_contains", "value": "interest on capital"}, {"field": "ledger", "op": "not_contains", "value": "work in"}]}'::jsonb, '''{account}'' is grouped as a capital / partner''s / proprietor''s account or reserve, yet it stands at a DEBIT balance of Rs.{amount} at the year end. Please explain WHY the account has gone into debit — drawings in excess of capital and share of profits, personal expenses or the owner''s income tax and advance tax charged to capital, accumulated losses absorbed against capital, an asset or receivable wrongly parked under the capital group, or a posting error. Kindly furnish the year''s movement statement of the account, segregate any tax and interest element that has been lumped into a single debit (interest on tax being a disallowable personal item), confirm whether the debit is recoverable from the owner or partner, and regroup any amount that is really a loan or advance to the owner, or an asset, out of capital into Loans & Advances or the correct head with the disclosure that entails.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- CUT-204: Prior-period item booked in the current year
-- measured: 19 findings across 12 engagements (1.6 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('CUT-204', 'Prior-period item booked in the current year', 'CUT', 'voucher',
  '{"check": "expr", "grain": "voucher", "where": [{"any": [{"field": "narration", "op": "contains", "value": "prior period"}, {"field": "narration", "op": "contains", "value": "prior year"}, {"field": "narration", "op": "contains", "value": "previous year"}, {"field": "narration", "op": "contains", "value": "earlier year"}, {"field": "narration", "op": "contains", "value": "preceding year"}, {"field": "narration", "op": "contains", "value": "last year"}, {"field": "narration", "op": "contains", "value": "earlier period"}, {"field": "narration", "op": "contains", "value": "opening difference"}, {"field": "narration", "op": "contains", "value": "pertains to f.y."}, {"field": "narration", "op": "contains", "value": "pertaining to f.y."}, {"field": "narration", "op": "contains", "value": "relates to f.y."}, {"field": "narration", "op": "contains", "value": "relating to f.y."}, {"field": "narration", "op": "contains", "value": "belongs to f.y."}, {"field": "narration", "op": "contains", "value": "belonging to f.y."}, {"field": "narration", "op": "contains", "value": "previous f.y."}, {"field": "narration", "op": "contains", "value": "earlier f.y."}, {"field": "narration", "op": "contains", "value": "last f.y."}]}, {"field": "abs_amount", "op": ">=", "value": 1000}]}'::jsonb, 'The voucher dated {date} in ''{account}'' for Rs.{amount} carries a narration indicating that it belongs to an earlier financial year: "{narration}". Please confirm the period to which this item actually relates and explain WHY it was recorded only in the current year. If the liability or the income had already crystallised before 31 March of the earlier year, this is a cut-off failure and the earlier year''s results stand misstated. Kindly furnish the underlying bill or supporting document with its date, and either disclose the amount separately as a prior-period item in the Statement of Profit and Loss as required by AS-5 (Ind AS 8, where applicable, requires retrospective restatement of a material error) or restate the comparatives, so that current-year profit is not distorted by an expense or income belonging to an earlier period.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- DORM-201: Dormant trade party balance — opening and closing identical, no movement all year
-- measured: 344 findings across 56 engagements (6.1 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('DORM-201', 'Dormant trade party balance — opening and closing identical, no movement all year', 'DORM', 'account',
  '{"check": "no_movement", "scope": {"parent_group_keywords": ["debtor", "creditor", "trade receivable", "trade payable"], "nonzero": true}, "min_balance": 100000, "tolerance": 100}'::jsonb, '{account} carries a closing balance of Rs.{amount}, which is identical to its opening balance — not a single invoice, payment, credit note or adjustment has touched this party ledger for the entire year. Please explain WHY this account has stayed completely dormant: is the party still dealing with us, is the amount disputed or under litigation, or has it simply never been knocked off against the corresponding bills? Kindly furnish a signed balance confirmation from the party as at the year end together with the bill-wise ageing of the underlying items, and confirm whether the amount is still legally recoverable or payable. If a receivable is no longer recoverable it must be provided for or written off in the current year, and if a payable represents a ceased liability it must be written back to income under section 41(1) now rather than being carried forward for another year. Also confirm whether the balance sits on its normal side — a debit lying in a creditor account or a credit lying in a debtor account is an advance, and must be regrouped as such, with the GST time-of-supply and revenue-recognition consequences of that advance addressed.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- DORM-202: Trivial residual party balance — settle or write off and close the ledger
-- measured: 101 findings across 34 engagements (3.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('DORM-202', 'Trivial residual party balance — settle or write off and close the ledger', 'DORM', 'account',
  '{"check": "expr", "grain": "account", "scope": {"parent_group_keywords": ["debtor", "creditor", "trade receivable", "trade payable"], "nonzero": true}, "where": [{"field": "abs_closing", "op": "between", "value": [0.01, 1000]}]}'::jsonb, '{account} is left with a residual closing balance of only Rs.{amount}, the account being otherwise fully settled. A balance of this size is almost never a genuine receivable or payable. Please explain WHY it is still open — is it a short payment or short receipt, an unadjusted cash discount or rate difference, a part payment posted without knocking off the invoice, a TDS or GST-TDS deduction by the party whose credit has not been taken, or a bill booked in the wrong period? Kindly obtain the party''s confirmation and either settle the amount against the correct invoice or pass a journal transferring it to Kasar / Discount Allowed (for debit stubs) or Discount Received / Sundry Balances Written Back (for credit stubs), and then close the ledger. Before writing anything off, please first confirm the stub is not a TDS credit deducted by the customer — that must be moved to TDS Receivable and claimed, never absorbed into Kasar — so that the Balance Sheet stops carrying dead sub-rupee and sub-thousand party balances.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- EXP-201: Profit & Loss head carrying a balance on the wrong side (expense in credit / income in debit)
-- measured: 20 findings across 13 engagements (1.5 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('EXP-201', 'Profit & Loss head carrying a balance on the wrong side (expense in credit / income in debit)', 'EXP', 'account',
  '{"check": "expr", "grain": "account", "scope": {"parent_group_keywords": ["direct expen", "direct income", "sales account", "purchase account"], "nonzero": true}, "where": {"all": [{"field": "ledger", "op": "not_contains", "value": "round"}, {"field": "ledger", "op": "not_contains", "value": "kasar"}, {"field": "ledger", "op": "not_contains", "value": "discount"}, {"field": "ledger", "op": "not_contains", "value": "payable"}, {"field": "ledger", "op": "not_contains", "value": "provision"}, {"field": "ledger", "op": "not_contains", "value": "outstanding"}, {"field": "ledger", "op": "not_contains", "value": "return"}, {"field": "ledger", "op": "not_contains", "value": "suspense"}, {"field": "ledger", "op": "not_contains", "value": "defer"}, {"field": "ledger", "op": "not_contains", "value": "gain"}, {"field": "parent_group", "op": "not_contains", "value": "creditor"}, {"field": "parent_group", "op": "not_contains", "value": "debtor"}, {"field": "parent_group", "op": "not_contains", "value": "payable"}, {"field": "parent_group", "op": "not_contains", "value": "receivable"}, {"field": "parent_group", "op": "not_contains", "value": "outstanding"}, {"field": "parent_group", "op": "not_contains", "value": "provision"}, {"field": "parent_group", "op": "not_contains", "value": "sundry"}, {"field": "parent_group", "op": "not_contains", "value": "advance"}, {"field": "parent_group", "op": "not_contains", "value": "loan"}, {"field": "parent_group", "op": "not_contains", "value": "deposit"}, {"field": "parent_group", "op": "not_contains", "value": "duties"}, {"any": [{"all": [{"field": "parent_group", "op": "contains", "value": "direct expen"}, {"field": "closing", "op": "<", "value": -50000}]}, {"all": [{"field": "parent_group", "op": "contains", "value": "purchase account"}, {"field": "closing", "op": "<", "value": -50000}]}, {"all": [{"field": "parent_group", "op": "contains", "value": "direct income"}, {"field": "closing", "op": ">", "value": 50000}]}, {"all": [{"field": "parent_group", "op": "contains", "value": "sales account"}, {"field": "closing", "op": ">", "value": 50000}]}]}]}}'::jsonb, '''{account}'' is a Profit & Loss head yet it closes on the wrong side with a balance of Rs.{amount} — an expense or purchase head cannot end the year in credit, and an income or sales head cannot end the year in debit. Please explain WHY: is a recovery from employees or a supplier credit note being parked in an expense head instead of a liability, has a bill been reversed without reversing the corresponding entry, has a receipt been posted directly to the income head, or is this simply a mis-posting? Kindly split the head correctly — charge the genuine current-year expense or income to the P&L and carry any recovery, unbilled or unpaid portion to the appropriate liability or asset head — and pass the rectification entry so that the ledger closes on its natural side.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- FA-202: Depreciation not charged, or charged inadequately, against the fixed asset block carried
-- measured: 23 findings across 23 engagements (1.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('FA-202', 'Depreciation not charged, or charged inadequately, against the fixed asset block carried', 'FA', 'aggregate',
  '{"check": "adequacy", "actual": {"ledger_keywords": ["deprecia", "amortis", "amortiz", "depn"], "side": "Dr"}, "base": {"parent_group_keywords": ["fixed asset", "tangible asset", "intangible asset", "property plant", "property, plant", "plant & machinery", "plant and machinery", "machinery & plant", "machinery and plant", "furniture & fixture", "furniture and fixture", "furniture & fitting", "furniture and fitting", "motor vehicle", "office equipment", "computer asset"], "side": "Dr"}, "pct": 5, "op": "<", "min_base": 500000}'::jsonb, 'Depreciation and amortisation of only Rs.{amount} has been debited for the year, against a fixed asset block that would require a charge of at least Rs.{value} even at a nominal {pct}% of its carrying value. Where the figure is nil, no depreciation entry has been passed at all for the year. A charge of this size is not commensurate with the assets held - computers and printers attract 40%, plant and machinery 15%, and buildings and electrical installations 10%. Please explain WHY the charge falls so far short: were the assets not put to use during the year, has a wrong rate or block been applied, has an entire block been left out of the working, were the year''s additions omitted, or was the entry simply forgotten at finalisation? Kindly furnish the block-wise fixed asset register showing opening WDV, additions with the date of put-to-use, deletions and the rate applied for each block, reconcile it to the amount actually debited to the Depreciation / Amortisation ledgers, and pass the differential depreciation entry - pro-rata from the date of put-to-use under Schedule II, and at half rate under the Income-tax Act for any asset used for less than 180 days. Until this is done both the profit for the year and the closing net block are overstated, and the consequential deferred tax on the book-WDV versus tax-WDV difference also remains unrecorded.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- FA-203: Below-de-minimis / revenue-nature item capitalised to a fixed asset block
-- measured: 26 findings across 11 engagements (2.4 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('FA-203', 'Below-de-minimis / revenue-nature item capitalised to a fixed asset block', 'FA', 'voucher',
  '{"check": "expr", "grain": "voucher", "scope": {"match_legs": true, "voucher_type": ["purchase", "payment"], "parent_group_keywords": ["fixed asset", "property plant", "property, plant", "plant & machinery", "plant and machinery", "furniture & fixture", "furniture and fixture", "furniture & fitting", "office equipment", "computer asset", "computer & laptop", "computer equipment", "computer system"]}, "where": [{"field": "abs_amount", "op": ">", "value": 0}, {"field": "abs_amount", "op": "<", "value": 5000}]}'::jsonb, 'Voucher {date} with ''{account}'' for Rs.{amount} posts an amount to a fixed asset block, but the whole voucher is below any reasonable capitalisation threshold. Items of this value — keyboards, cables, small tools, replacement parts, books, consumables — have no independent useful life and fail the AS-10 / Ind AS-16 recognition test. Please explain WHY this has been capitalised rather than charged to revenue: does the entity have a written capitalisation policy, and if so what is its de-minimis limit? If there is no justification, kindly reclassify the amount to the appropriate expense head (Computer / Office Expenses / Repairs & Maintenance), reverse the depreciation charged on it for the year, and remove the corresponding line from the fixed asset register and the Income-tax depreciation working.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- GST-201: Same customer billed under both intra-state (CGST/SGST) and inter-state (IGST) heads
-- measured: 24 findings across 4 engagements (6.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('GST-201', 'Same customer billed under both intra-state (CGST/SGST) and inter-state (IGST) heads', 'GST', 'account',
  '{"check": "cotag", "sets": [["cgst", "sgst", "utgst", "local gst"], ["igst", "integrated gst"]], "scope": {"voucher_type": ["Sales"], "parent_group_keywords": ["debtor", "receivable", "customer"]}}'::jsonb, 'In the account of {account}, sales during the year have been booked under BOTH the intra-state head (CGST/SGST) and the inter-state head (IGST). For a single registered place of supply the supply cannot be both intra-state and inter-state, so one of the two heads must be wrong. Please explain WHY the same customer has been charged CGST/SGST on some invoices and IGST on others — was there a genuine change in the ship-to state or GSTIN during the year, or a wrong tax head at the time of invoicing? Kindly identify the invoices carrying the wrong head against the party''s GSTIN and place of supply, correct the head in the books, and amend GSTR-1 for the affected invoices; where tax was paid under the wrong head, confirm the re-payment under the correct head and the status of the refund claim for the head wrongly paid.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- GST-203: GST control ledger carries a material balance with no movement all year — set-off never passed
-- measured: 6 findings across 4 engagements (1.5 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('GST-203', 'GST control ledger carries a material balance with no movement all year — set-off never passed', 'GST', 'account',
  '{"check": "no_movement", "scope": {"nonzero": true, "ledger_keywords": ["Input CGST", "Input SGST", "Input IGST", "Output CGST", "Output SGST", "Output IGST", "GST Payable", "GST Credit", "GST Receivable", "CGST Receivable", "SGST Receivable", "IGST Receivable", "Suspended CGST", "Suspended SGST", "Suspended IGST", "Input Tax Credit", "ITC Receivable", "GST Input", "Electronic Credit Ledger"], "parent_group_keywords": ["GST", "Duties & Taxes", "Duties and Taxes", "Current Assets", "Current Liabilities", "Loans & Advances (Asset)"]}, "min_balance": 100000, "tolerance": 100}'::jsonb, 'The GST control ledger {account} carries a balance of {amount} as at the year end that is unchanged from its opening balance — no set-off, payment or adjustment entry touched this ledger during the entire year. Please explain WHY the monthly CGST/SGST/IGST set-off journals have not been passed against this ledger in the utilisation sequence prescribed u/s 49/49A. Kindly pass the month-wise set-off entries, reconcile the resulting net balance with the Electronic Credit and Cash Ledgers and with the returns filed for the year, and where the credit is no longer utilisable or has become time-barred u/s 16(4), write it off to GST Expense in the Profit & Loss account instead of carrying it in the Balance Sheet.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- GST-204: Same supplier's purchases booked across two different GST rate heads (5% vs 18%)
-- measured: 96 findings across 43 engagements (2.2 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('GST-204', 'Same supplier''s purchases booked across two different GST rate heads (5% vs 18%)', 'GST', 'voucher',
  '{"check": "cotag", "sets": [[" 5%", "-5%", "@5%", " 2.5%", "-2.5%", "@2.5%", "gst5%", "gst2.5%", "purchase5%", "input5%", "tax5%"], [" 18%", "-18%", "@18%", " 9%", "-9%", "@9%", "gst18%", "gst9%", "purchase18%", "input18%", "tax18%"]], "scope": {"voucher_type": ["Purchase"], "parent_group_keywords": ["creditor", "payable"]}}'::jsonb, 'Purchases from {account} have been booked during the year under two different GST rate heads — the 5% slab (IGST 5% / CGST+SGST 2.5% each) and the 18% slab (IGST 18% / CGST+SGST 9% each). Please explain WHY supplies from the same vendor attract two different rates. Kindly establish, item-wise against the HSN code on each invoice, that the rate head applied is correct for the goods or services actually supplied, and confirm the input tax credit availed at each rate agrees with the vendor''s GSTR-1 as reflected in your GSTR-2B. Where the rate head is wrong, the ITC availed is either excess or short and must be reversed or claimed with interest u/s 50; where the correct rate has been charged but the wrong ledger used, please re-post the entry to the correct rate head so that the ITC register and GSTR-3B reconcile. Where a supply is in fact exempt or from an unregistered dealer, confirm whether reverse charge u/s 9(3)/9(4) applies and has been discharged.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- GST-205: Input tax credit head standing on the wrong side (credit balance in an input-credit ledger)
-- measured: 2 findings across 2 engagements (1.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('GST-205', 'Input tax credit head standing on the wrong side (credit balance in an input-credit ledger)', 'GST', 'account',
  '{"check": "expr", "grain": "account", "scope": {"ledger_keywords": ["input cgst", "cgst input", "input sgst", "sgst input", "input igst", "igst input", "input ugst", "ugst input", "input gst", "gst input", "input tax credit", "itc receivable", "itc cgst", "itc sgst", "itc igst", "input vat", "vat input", "input credit", "input duty", "cenvat credit"], "nonzero": true}, "where": [{"field": "closing", "op": "<", "value": -50000}]}'::jsonb, '''{account}'' is an input-tax-credit head, but it closes on the WRONG SIDE at the year end — it stands in CREDIT, with a closing balance of Rs.{amount}. Input credit is an asset (a receivable from the Government) and can never close in credit; a credit balance here means either the credit has been utilised in the books beyond what was actually available, or a liability has been posted into an asset head. Please explain WHY this reversal has arisen — has the monthly set-off or RCM journal been passed for more than the credit available, has an output liability or a cash GST payment been posted into the input head instead of ''GST Payable'', has an ITC reversal under Rule 37/42/43 or a supplier credit note been booked without reversing the matching entry, or is the head simply mis-grouped? Kindly reconcile the ledger month-wise against GSTR-2B, GSTR-3B and the Electronic Credit Ledger, pass the correcting entry, and regroup any genuine net liability to ''GST Payable'' under Current Liabilities so that the head closes on its natural (debit) side.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- LOAN-201: Interest-bearing deposits held but little or no interest income recognised
-- measured: 8 findings across 8 engagements (1.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('LOAN-201', 'Interest-bearing deposits held but little or no interest income recognised', 'LOAN', 'aggregate',
  '{"check": "adequacy", "actual": {"ledger_keywords": ["interest received", "interest income", "interest on fd", "fd interest", "deposit interest", "interest earned", "interest from", "interest recd", "int received", "interest on deposit", "interest on sweep", "interest on bond", "interest on debenture", "interest on securities", "bank interest", "sb interest", "interest on saving", "savings interest", "accrued interest", "interest accrued"], "side": "Cr"}, "base": {"ledger_keywords": ["fixed deposit", "fdr", "term deposit", "f.d.", "fd ", "recurring deposit", "margin money", "deposit with bank", "bond", "debenture", "national saving"], "side": "Dr"}, "pct": 3, "op": "<", "min_base": 500000}'::jsonb, 'Interest income of only Rs.{amount} has been recognised for the year, against interest-bearing deposits and securities (fixed deposits, term and recurring deposits, margin money, bonds and debentures held) whose closing balances would yield at least Rs.{value} even at a nominal {pct}% per annum. Where the amount recognised is nil, no interest income has been credited anywhere in the books at all. Interest on a deposit accrues over its tenure whether or not the bank or issuer has actually credited or paid it, so a deposit that matures after the year end still carries accrued interest at 31 March. Please explain WHY the income has not been recognised, and book the interest accrued up to the year end on an accrual basis, gross of TDS, strictly as per the bank or issuer interest certificate — recognising the corresponding TDS receivable so that the principal, the interest income and the TDS credit tie out. Kindly also reconcile the interest recognised with Form 26AS / AIS for the year, and confirm that any deposit included above is genuinely non-interest-bearing if that is the reason for the shortfall.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- LOAN-202: Borrowings outstanding at the year end with no interest expense charged
-- measured: 36 findings across 36 engagements (1.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('LOAN-202', 'Borrowings outstanding at the year end with no interest expense charged', 'LOAN', 'aggregate',
  '{"check": "adequacy", "actual": {"side": "Dr", "ledger_keywords": ["interest paid", "interest expense", "interest on loan", "interest on unsecured", "interest on secured", "interest on term", "interest on borrow", "loan interest", "interest to director", "interest to partner", "int paid", "interest exp", "bank interest", "finance cost", "finance charges", "interest on working capital"]}, "base": {"side": "Cr", "nonzero": true, "parent_group_keywords": ["unsecured loan", "secured loan", "borrowing", "loans (liability)", "loan from", "partner''s loan", "partners loan", "long & short term borrowing", "term loan"]}, "pct": 4, "op": "<", "min_base": 500000}'::jsonb, 'Against borrowings outstanding at the year end, interest of only Rs.{amount} has been charged to the Profit & Loss account for the year — less than the Rs.{value} that these loans would carry even at a nominal {pct}%. Where the amount is nil, not a single rupee of interest has been charged on any borrowing during the year. Please explain WHY the loans are being carried interest-free or at so low a charge, and furnish the loan agreements together with lender confirmations as at the year end stating the principal outstanding, the rate of interest and the repayment terms. If interest is in fact payable, provide for the interest accrued for the full period the loan was outstanding and deduct TDS u/s 194A on the amount credited, whether paid or merely credited to the lender''s account. If a loan is genuinely interest-free and the lender is a director, partner, shareholder or other related party, obtain that confirmation in writing, disclose it in the related-party note, and confirm that both the receipt and the repayment were routed through banking channels so that ss.269SS/269T are not attracted.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- MISC-202: Debit balance sitting in a provision / statutory-dues / borrowing head
-- measured: 15 findings across 9 engagements (1.7 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('MISC-202', 'Debit balance sitting in a provision / statutory-dues / borrowing head', 'MISC', 'account',
  '{"check": "expr", "grain": "account", "scope": {"parent_group_keywords": ["provision", "duties & taxes", "duties and taxes", "statutory", "unsecured loan", "secured loan", "loans (liability)", "borrowing"], "nonzero": true}, "where": [{"field": "closing", "op": ">", "value": 50000}, {"field": "ledger", "op": "not_contains", "value": "tds"}, {"field": "ledger", "op": "not_contains", "value": "tcs"}, {"field": "ledger", "op": "not_contains", "value": "input"}, {"field": "ledger", "op": "not_contains", "value": "purchase"}, {"field": "ledger", "op": "not_contains", "value": "receivable"}, {"field": "ledger", "op": "not_contains", "value": "advance"}, {"field": "ledger", "op": "not_contains", "value": "refund"}, {"field": "ledger", "op": "not_contains", "value": "payable"}, {"field": "ledger", "op": "not_contains", "value": "creditor"}, {"field": "parent_group", "op": "not_contains", "value": "asset"}, {"field": "parent_group", "op": "not_contains", "value": "payment to and provision"}]}'::jsonb, 'Ledger ''{account}'' is grouped under a credit-natural head (provision / statutory dues / borrowings) but carries a DEBIT balance of Rs.{amount} as at the year end. A provision, a statutory liability or a loan account standing in debit usually means one of four things: the provision was reversed or the payment made exceeds the expense actually booked, i.e. the expense is short-booked; a challan has been paid and debited here but never set off against the corresponding output liability; an excess or wrong-head challan has been debited to this account; or a repayment has been posted without the corresponding liability entry. Please explain WHY this account is in debit and reconcile it with the underlying bills, challans, returns and lender statements. Where it is a GST or other statutory head, tie the debit back to the return filed for the period and set it off against the output liability rather than carrying it forward as a debit. Where it is a loan or borrowing head, confirm with the lender''s statement whether the account has genuinely been over-repaid or whether this is in substance a loan GIVEN that has been misgrouped under liabilities. Otherwise either book the balance expense (with the related TDS/PF/ESI consequences) or regroup the debit to Advances / Balances with Government Authorities under current assets. Where the debit represents interest or late fee on statutory dues, transfer it to a separate disallowable expense ledger rather than leaving it inside the liability head.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- MISC-203: Ledger name declares a nature its parent group contradicts
-- measured: 16 findings across 8 engagements (2.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('MISC-203', 'Ledger name declares a nature its parent group contradicts', 'MISC', 'account',
  '{"check": "expr", "grain": "account", "scope": {"ledger_keywords": ["bank ltd", "bank limited", "credit card", "hdfc bank", "icici bank", "axis bank", "yes bank", "state bank", "bank of ", "finserv", "housing finance", "fincorp", "finance ltd", "l.i.c", "life insurance", "mediclaim", "term plan", "deferred tax"], "parent_group_keywords": ["sundry debtor", "sundry creditor", "trade receivable", "trade payable", "current asset", "loans & advances", "share capital"], "nonzero": true}, "where": [{"field": "ledger", "op": "not_contains", "value": "prepaid"}, {"field": "ledger", "op": "not_contains", "value": "deposit"}, {"field": "ledger", "op": "not_contains", "value": "charge"}, {"field": "ledger", "op": "not_contains", "value": "forex"}, {"field": "abs_closing", "op": ">", "value": 25000}]}'::jsonb, 'Ledger ''{account}'' carries a balance of Rs.{amount} but is grouped under a head that contradicts its own name — a bank / NBFC / credit-card / insurance / deferred-tax item cannot sit inside Trade Receivables, Trade Payables, Investments, Share Capital or a general Current Assets head. Credit-card and financier balances are borrowings and belong under Other Financial Liabilities, a bank account belongs under Bank Accounts, deferred tax must be shown separately under Non-Current Assets/Liabilities per Schedule III, and a proprietor''s LIC or term-plan premium is personal and belongs to the capital account. Please confirm the true nature of this ledger, explain WHY it was created under the present group, and regroup it to the correct Schedule III head.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- MISC-204: Adjustment / rounding / write-off bucket ledger carrying a material balance
-- measured: 52 findings across 37 engagements (1.4 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('MISC-204', 'Adjustment / rounding / write-off bucket ledger carrying a material balance', 'MISC', 'account',
  '{"check": "expr", "grain": "account", "scope": {"nonzero": true, "ledger_keywords": ["kasar", "vatav", "round off", "round-off", "roundoff", "round figure", "rounding", "difference a/c", "diff a/c", "difference in books", "adjustment a/c", "adjustment account", "bad debt", "bed debt", "written off", "write off", "write-off", "w/off", "sundry balance", "discount allowed", "misc.", "misc exp", "miscellaneous", "sundry expense", "general expense", "other expense", "temp ", "dummy", "to be identified", "unknown"]}, "where": {"all": [{"field": "abs_closing", "op": ">", "value": 10000}, {"any": [{"field": "ledger", "op": "contains", "value": "kasar"}, {"field": "ledger", "op": "contains", "value": "vatav"}, {"field": "ledger", "op": "contains", "value": "round off"}, {"field": "ledger", "op": "contains", "value": "round-off"}, {"field": "ledger", "op": "contains", "value": "roundoff"}, {"field": "ledger", "op": "contains", "value": "round figure"}, {"field": "ledger", "op": "contains", "value": "rounding"}, {"field": "ledger", "op": "contains", "value": "difference a/c"}, {"field": "ledger", "op": "contains", "value": "diff a/c"}, {"field": "ledger", "op": "contains", "value": "difference in books"}, {"field": "ledger", "op": "contains", "value": "adjustment a/c"}, {"field": "ledger", "op": "contains", "value": "adjustment account"}, {"field": "ledger", "op": "contains", "value": "bad debt"}, {"field": "ledger", "op": "contains", "value": "bed debt"}, {"field": "ledger", "op": "contains", "value": "written off"}, {"field": "ledger", "op": "contains", "value": "write off"}, {"field": "ledger", "op": "contains", "value": "write-off"}, {"field": "ledger", "op": "contains", "value": "w/off"}, {"field": "ledger", "op": "contains", "value": "sundry balance"}, {"field": "ledger", "op": "contains", "value": "discount allowed"}, {"field": "ledger", "op": "contains", "value": "misc."}, {"field": "ledger", "op": "contains", "value": "misc exp"}, {"field": "ledger", "op": "contains", "value": "miscellaneous"}, {"field": "ledger", "op": "contains", "value": "sundry expense"}, {"field": "ledger", "op": "contains", "value": "general expense"}, {"field": "ledger", "op": "contains", "value": "other expense"}, {"field": "ledger", "op": "contains", "value": "temp "}, {"field": "ledger", "op": "contains", "value": "dummy"}, {"field": "ledger", "op": "contains", "value": "to be identified"}, {"field": "ledger", "op": "contains", "value": "unknown"}]}]}}'::jsonb, 'Ledger ''{account}'' carries a balance of Rs.{amount}, which is far too large to be a genuine rounding, kasar/vatav or miscellaneous adjustment. Balances of this size routed through a round-off, write-off or undifferentiated ''general/other expense'' head normally conceal a trade discount or rate difference, an irrecoverable debtor written off, TDS deducted by the customer, a foreign-exchange gain or loss, or expenditure that was never allocated to its proper natural head. Please give us the party-wise and item-wise break-up with the date and reason for each posting, and explain WHY each item was absorbed here rather than in its correct head — a trade discount or rate difference requires a GST credit note u/s 34; a customer deduction such as TDS/TCS or liquidated damages must be shown as a tax credit or as an expense in its own right; an exchange difference on a foreign-currency party must go through Foreign Exchange Gain/Loss; and a creditor balance no longer payable must be credited to ''Liabilities Written Back'' and offered to tax u/s 41(1) — it cannot be routed as a bad debt, since no deduction u/s 36(1)(vii) is available on an amount never offered as income. Kindly reverse the entries, reclassify each item to its proper head, and clear this bucket ledger to nil.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- PAY-201: Employee / staff payable ledger carrying an abnormal debit balance
-- measured: 4 findings across 2 engagements (2.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('PAY-201', 'Employee / staff payable ledger carrying an abnormal debit balance', 'PAY', 'account',
  '{"check": "expr", "grain": "account", "scope": {"nonzero": true, "parent_group_keywords": ["unpaid staff salary", "unpaid salary", "unpaid remunerat", "unpaid wages", "salary payable", "salaries payable", "wages payable", "remuneration payable", "bonus payable", "staff payable", "employee payable", "payroll liab", "salary outstanding", "outstanding salary", "outstanding wages", "staff dues", "employee dues"]}, "where": [{"field": "closing", "op": ">", "value": 100000}, {"field": "parent_group", "op": "not_contains", "value": "expen"}, {"field": "parent_group", "op": "not_contains", "value": "asset"}, {"field": "parent_group", "op": "not_contains", "value": "advance"}, {"field": "parent_group", "op": "not_contains", "value": "loan"}, {"field": "parent_group", "op": "not_contains", "value": "receivable"}, {"field": "parent_group", "op": "not_contains", "value": "recoverable"}, {"field": "parent_group", "op": "not_contains", "value": "creditor"}, {"field": "ledger", "op": "not_contains", "value": "advance"}, {"field": "ledger", "op": "not_contains", "value": "loan"}, {"field": "ledger", "op": "not_contains", "value": "imprest"}, {"field": "ledger", "op": "not_contains", "value": "receivable"}, {"field": "ledger", "op": "not_contains", "value": "recoverable"}, {"field": "ledger", "op": "not_contains", "value": "payable"}, {"field": "ledger", "op": "not_contains", "value": "creditor"}, {"field": "ledger", "op": "not_contains", "value": "exp"}, {"field": "ledger", "op": "not_contains", "value": "contri"}, {"field": "ledger", "op": "not_contains", "value": "welfare"}]}'::jsonb, '''{account}'' is grouped under an employee / staff payable head but closes the year with a DEBIT balance of Rs.{amount}. A salary, remuneration or employee-dues payable account should never stand as an asset. A debit here means one of three things: salary has been paid or advanced without the corresponding expense being booked (understating Employee Benefits Expense and overstating assets), or an excess / duplicate payment has gone out of the bank, or a receipt has been wrongly credited into a payable head. Please explain WHY this account is in debit and produce the employee-wise, month-wise reconciliation of amounts booked against amounts paid, together with the bank statement lines for the payments. If the expense is short-booked, pass the balancing salary entry and settle its PF / ESI and section 192 TDS consequences for the affected months. If the balance is in substance an advance or loan to an employee, regroup it to Loans & Advances under Current Assets and confirm section 17(2)(viii) perquisite treatment where it is interest-free — it cannot remain sitting in a payable head.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- PAY-203: TDS not deducted on salary and director remuneration (section 192)
-- measured: 4 findings across 4 engagements (1.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('PAY-203', 'TDS not deducted on salary and director remuneration (section 192)', 'PAY', 'account',
  '{"check": "tds_shortfall", "tolerance": 0.05, "sections": [{"section": "192", "keywords": ["director remuneration", "directors remuneration", "director''s remuneration", "remuneration to director", "managerial remuneration", "remuneration to staff", "staff remuneration", "whole time director"], "rate": 0.05, "individual_rate": 0.05, "threshold": 1275000}]}'::jsonb, 'Rs.{value} of salary / remuneration has been booked against ''{account}'' during the year, but the TDS routed against that party falls short by Rs.{amount} of even a conservative {pct}% floor. Salary is deductible u/s 192 at each payee''s OWN slab rate on his estimated total income, not at any flat rate, so the shortfall shown here is indicative only — this test merely asks whether a plausible minimum was withheld at all. Please explain WHY no deduction, or a materially lower deduction, was made: was the payee''s estimated income below the taxable limit (a salaried individual bears nil tax up to Rs.12,75,000 for FY 2025-26 under the default regime after standard deduction), are the Chapter VI-A / house-property declarations and the 115BAC option on record, and is the employee-wise computation supporting Form 16 and Annexure II of the Q4 24Q available for inspection? If TDS was in fact deducted but was never routed through a TDS liability ledger, produce the challan and pass the correcting entry. If it was genuinely not deducted, recover and deposit it with interest u/s 201(1A) at 1%/1.5% per month and file the correction statement — failing which 30% of the expenditure is liable to disallowance u/s 40(a)(ia) and the entity is an assessee-in-default u/s 201(1), besides late-fee exposure u/s 234E.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- PAY-204: Employee-cost ledger grouped outside Employee Benefits Expense
-- measured: 21 findings across 18 engagements (1.2 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('PAY-204', 'Employee-cost ledger grouped outside Employee Benefits Expense', 'PAY', 'account',
  '{"check": "expr", "grain": "account", "scope": {"ledger_keywords": ["bonus", "gratuity", "leave encashment", "ex-gratia", "exgratia", "incentive", "stipend", "overtime"], "parent_group_keywords": ["expense", "exp", "overhead", "cost", "charges", "marketing", "selling", "admin", "misc"], "nonzero": true}, "where": [{"field": "abs_closing", "op": ">", "value": 100000}, {"field": "parent_group", "op": "not_contains", "value": "employee"}, {"field": "parent_group", "op": "not_contains", "value": "salar"}, {"field": "parent_group", "op": "not_contains", "value": "staff"}, {"field": "parent_group", "op": "not_contains", "value": "payroll"}, {"field": "parent_group", "op": "not_contains", "value": "personnel"}, {"field": "parent_group", "op": "not_contains", "value": "wage"}, {"field": "parent_group", "op": "not_contains", "value": "remunerat"}, {"field": "parent_group", "op": "not_contains", "value": "remunarat"}, {"field": "parent_group", "op": "not_contains", "value": "payable"}, {"field": "parent_group", "op": "not_contains", "value": "provision"}, {"field": "parent_group", "op": "not_contains", "value": "outstanding"}, {"field": "parent_group", "op": "not_contains", "value": "liabilit"}, {"field": "parent_group", "op": "not_contains", "value": "reserve"}, {"field": "parent_group", "op": "not_contains", "value": "asset"}, {"field": "parent_group", "op": "not_contains", "value": "creditor"}, {"field": "parent_group", "op": "not_contains", "value": "loan"}, {"field": "parent_group", "op": "not_contains", "value": "capital"}, {"field": "parent_group", "op": "not_contains", "value": "deposit"}, {"field": "parent_group", "op": "not_contains", "value": "advance"}, {"field": "parent_group", "op": "not_contains", "value": "duties"}, {"any": [{"field": "ledger", "op": "contains", "value": "bonus"}, {"field": "ledger", "op": "contains", "value": "gratuity"}, {"field": "ledger", "op": "contains", "value": "leave encashment"}, {"field": "ledger", "op": "contains", "value": "ex-gratia"}, {"field": "ledger", "op": "contains", "value": "exgratia"}, {"field": "ledger", "op": "contains", "value": "incentive"}, {"field": "ledger", "op": "contains", "value": "stipend"}, {"field": "ledger", "op": "contains", "value": "overtime"}]}]}'::jsonb, '''{account}'' carries Rs.{amount} and sits in a general expense group in the trial balance instead of Employee Benefits Expense. Bonus, gratuity, leave encashment, ex-gratia, stipend, overtime and employee incentives are employee costs and must be disclosed within Employee Benefits Expense under Schedule III — the present grouping understates the disclosed employee cost and, where the ledger sits in Direct Expenses, also distorts gross profit. Please confirm WHY it has been grouped here and regroup it under Employee Benefits Expense. Kindly also give us the employee-wise break-up of this lump-sum charge so that we can verify it is payable to persons actually on the payroll, that it has been routed through the payroll and has suffered TDS u/s 192 (a payment to a non-employee would instead be commission/professional fees u/s 194H or 194J), and, in the case of bonus and gratuity, that it is within the eligibility and ceiling limits of the Payment of Bonus Act and is claimed only on actual payment as required by section 43B.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- PROV-201: Audit fee provision not created at the year end
-- measured: 9 findings across 9 engagements (1.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('PROV-201', 'Audit fee provision not created at the year end', 'PROV', 'aggregate',
  '{"check": "missing_provision", "keywords": ["audit fee", "statutory audit", "auditor remuneration", "auditors remuneration", "audit charges", "payment to auditor", "remuneration to auditor"]}'::jsonb, 'No audit fee ledger or year-end provision for audit fee appears anywhere in the trial balance. The liability for the statutory audit of the year has accrued as at the balance sheet date but has not been recognised, so audit fee expense and current liabilities (provisions) are both understated and the accrual basis of accounting is not followed. Please explain WHY the year-end audit fee provision has not been passed, confirm the fee agreed or approved by the Board / shareholders for the year, and pass the provision entry as at the year end (Dr Audit Fee, Cr Provision for Audit Fee) together with the TDS deductible u/s 194J on the amount provided. If the fee is genuinely borne by another entity or has already been recorded under a differently named ledger, please identify that ledger for us.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- PROV-205: Income-tax provision not created at the year end
-- measured: 92 findings across 92 engagements (1.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('PROV-205', 'Income-tax provision not created at the year end', 'PROV', 'aggregate',
  '{"check": "missing_provision", "keywords": ["provision for income tax", "provision of income tax", "income tax provision", "provision for income-tax", "income-tax provision", "provision for i.tax", "provision for i. tax", "i.tax provision", "provision for tax", "provision for current tax", "current tax provision", "tax exp. provision", "tax exp provision", "tax expense provision", "income tax payable", "income-tax payable"]}'::jsonb, 'No provision for income tax appears in the books as at the year end — there is no ledger such as "Provision for Income Tax" / "Provision for Taxation" / "Income Tax Payable" carrying a balance at the year end, even though ledgers for advance tax, TDS credits or tax charged straight to the profit and loss account on payment may well exist. The current tax liability for the year has accrued but has not been recognised, so the tax expense and current liabilities are both understated and the accrual basis is not followed. Please explain WHY the year-end provision entry has not been passed, furnish the computation of total income for the year showing the current tax payable (including the MAT / section 115BAA position and interest u/s 234B/234C), and pass the provision as at the year end, setting off the advance tax and TDS credits of the corresponding assessment year against it so that neither a fictitious receivable nor an unrecorded liability is carried forward. If the entity has a loss or nil taxable income for the year, please confirm that position in writing and state whether any MAT liability nonetheless arises.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- RC-201: Material amount routed through a Kasar / Round-Off ledger in a journal or settlement entry
-- measured: 287 findings across 51 engagements (5.6 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('RC-201', 'Material amount routed through a Kasar / Round-Off ledger in a journal or settlement entry', 'RC', 'voucher',
  '{"check": "expr", "grain": "voucher", "scope": {"match_legs": true, "voucher_type": ["Journal"], "ledger_keywords": ["kasar", "vatav"]}, "where": [{"field": "abs_amount", "op": ">=", "value": 2000}]}'::jsonb, 'The journal voucher dated {date} in the account of ''{account}'', totalling Rs.{amount}, carries a leg posted to a Kasar / Round-Off ledger. (The figure quoted is the total of the voucher, not of the rounding leg itself — please read it as the entry to be examined, not as the sum absorbed into the rounding head.) A genuine rounding difference is a mechanical few rupees arising on an invoice; it does not arise in a journal, receipt or payment entry. An item absorbed into a rounding head here is far more likely to be a rate difference or settlement discount, a short realisation on collection, TDS or GST deducted by the counterparty, an exchange-rate difference on a foreign-currency party, or a bad debt or write-back. Please explain WHY an identified item has been absorbed into a rounding ledger, where it escapes disclosure in the Statement of Profit and Loss, and state the nature and amount of each such posting with the party''s debit or credit note or payment advice. Kindly reverse the item out of the rounding ledger and re-book it to its correct head — Discount Allowed/Received, Bad Debts Written Off, TDS Receivable or Foreign Exchange Gain/Loss as applicable — and confirm the consequential GST credit note u/s 34, or taxability u/s 41(1) on any write-back, where relevant.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- RC-203: Cash payments to one party in one day above the s.40A(3) ceiling
-- measured: 53 findings across 21 engagements (2.5 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('RC-203', 'Cash payments to one party in one day above the s.40A(3) ceiling', 'RC', 'aggregate',
  '{"check": "expr", "grain": "aggregate", "scope": {"voucher_type": ["Payment"], "ledger_keywords": ["cash"], "match_legs": true}, "where": [{"field": "party", "op": "not_contains", "value": "cash"}], "aggregate": {"by": ["party", "date"], "fn": "sum", "field": "abs_amount", "having": {"op": ">", "value": 10000}}}'::jsonb, 'Cash payments to ''{account}'' on {date} aggregate to Rs.{amount} across {count} voucher(s). Section 40A(3) applies to the aggregate of payments made to a single person in a single day, not to each voucher separately — splitting one settlement into several sub-limit vouchers gives no relief, and this day''s aggregate exceeds the Rs.10,000 ceiling. Please explain WHY this expenditure was settled in cash when the payee is identifiable and banking channels were available. Kindly furnish the date-wise and party-wise listing with the underlying bills, and state which Rule 6DD exception is claimed (or, if the payee is a goods-transport operator, confirm eligibility for the higher Rs.35,000 limit under the proviso). Where no exception is available, add back 100% of the aggregate as a disallowance u/s 40A(3) in the computation of income.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- RC-204: Large cash receipts from one party in one day (269ST exposure)
-- measured: 9 findings across 5 engagements (1.8 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('RC-204', 'Large cash receipts from one party in one day (269ST exposure)', 'RC', 'aggregate',
  '{"check": "expr", "grain": "aggregate", "scope": {"voucher_type": ["Receipt"], "ledger_keywords": ["cash"], "match_legs": true}, "where": [{"field": "voucher_type", "op": "not_contains", "value": "note"}, {"field": "party", "op": "not_contains", "value": "cash"}, {"field": "party", "op": "not_contains", "value": "bank"}, {"field": "narration", "op": "not_contains", "value": "cash high"}, {"field": "narration", "op": "not_contains", "value": "dmt"}, {"field": "narration", "op": "not_contains", "value": "imps"}], "aggregate": {"by": ["party", "date"], "fn": "sum", "field": "abs_amount", "having": {"op": ">=", "value": 100000}}}'::jsonb, 'Cash received from ''{account}'' on {date} totals Rs.{amount} across {count} receipt(s). Section 269ST prohibits receiving Rs.2,00,000 or more from one person in a day, in respect of a single transaction, or in respect of one event or occasion — and the penalty u/s 271DA is equal to the ENTIRE amount received, not the excess. This aggregate is flagged at Rs.1,00,000 deliberately, so that split receipts are reviewed before they cross the statutory limit. Please explain WHY a party of this size is settling in cash rather than through banking channels, particularly where the rest of this account moves through the bank. Kindly provide the party-wise cash receipt listing with PAN, confirm that the aggregate per person per day, per transaction and per event stays below Rs.2,00,000, produce the signed receipts and the bank deposit slips evidencing that the cash was banked, and confirm these are not part-recoveries against one larger invoice — which would breach the single-transaction test independently of the daily limit. Where the cash route cannot be justified, route future collections through bank and record the reason on file.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- RG-201: Recurring monthly charge booked in fewer than twelve months
-- measured: 242 findings across 82 engagements (3.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('RG-201', 'Recurring monthly charge booked in fewer than twelve months', 'RG', 'aggregate',
  '{"check": "expr", "grain": "aggregate", "scope": {"match_legs": true, "ledger_keywords": ["electricity", "rent", "telephone", "mobile expense", "internet", "broadband", "water charges", "gas charges", "security charges", "housekeeping", "office rent", "godown rent"]}, "where": [{"field": "abs_amount", "op": ">=", "value": 1000}], "aggregate": {"by": ["leg"], "fn": "count_distinct", "field": "month", "having": {"op": "<", "value": 12}}}'::jsonb, '''{account}'' is a recurring monthly charge but has been booked in only {count} of the twelve months of the year, aggregating Rs.{amount}. Please explain WHY the remaining months carry no charge — are the bills for those months still unbooked (a cut-off failure that understates both the expense and the corresponding liability), has the charge been posted to a different head, or did the service genuinely not run for the full year? If bills are pending, book the outstanding liability before finalisation and confirm whether TDS was required on the unbooked amounts.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

