-- RG-203: Recurring expense/utility ledger whose bookings stop before the year end
-- measured: 49 findings across 26 engagements (1.9 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('RG-203', 'Recurring expense/utility ledger whose bookings stop before the year end', 'recurring_gap', 'account',
  '{"check": "ageing", "days": 90, "min_balance": 10000, "scope": {"nonzero": true, "side": "Dr", "parent_group_keywords": ["expens", "exps", "charges", "overhead"], "ledger_keywords": ["electricity", "electricty", "electric exp", "electric bill", "electric charge", "ugvcl", "dgvcl", "mgvcl", "pgvcl", "torrent power", "tata power", "adani electric", "telephone", "mobile exp", "internet exp", "broadband", "jio ", "airtel", "vodafone", "bsnl", "bank charge", "security exp", "housekeep", "cleaning", "courier exp", "water charge", "accounting charge", "office rent", "godown rent", "shop rent", "factory rent", "rent exp"]}}'::jsonb, '''{account}'' has been charged Rs.{amount} for the year, but the ledger falls silent well before 31-March — nothing at all has been posted to it in the closing months of the year, even though this is a charge that recurs every month. Please tell us why the postings stop. If the connection, tenancy or contract was actually discontinued or transferred during the year, kindly furnish the disconnection or termination letter and the final settlement so we can verify the closure. If it was not discontinued, the bills for the remaining months up to 31-March are lying unbooked: please obtain them and pass the expense, and where a bill for March is received only after the year end, raise a provision for the unbilled period — so that both the expense for the year and the corresponding trade payable are stated in full. Please also confirm the amounts have not been posted to some other ledger by mistake.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- TDS-210: TDS not deducted / short-deducted / wrong section on expense and purchase heads
-- measured: 406 findings across 80 engagements (5.1 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('TDS-210', 'TDS not deducted / short-deducted / wrong section on expense and purchase heads', 'TDS', 'account',
  '{"check": "tds_shortfall", "tolerance": 0.05, "sections": [{"section": "194T", "keywords": ["remuneration to partner", "partner remuneration", "partners remuneration", "partner''s remuneration", "interest to partner", "interest on partner capital", "interest on capital", "partner commission", "commission to partner", "partners salary", "partner salary"], "rate": 0.1, "individual_rate": 0.1, "threshold": 20000}, {"section": "194C", "keywords": ["labour", "labour charges", "labour charge", "job work", "jobwork", "contract", "contractor", "sub contract", "subcontract", "freight", "carting", "cartage", "carriage", "transport", "fabrication", "processing charges", "erection", "installation", "printing", "courier", "security charges", "housekeeping"], "rate": 0.02, "individual_rate": 0.01, "threshold": 100000}, {"section": "194J", "keywords": ["professional", "professional fees", "consultanc", "consultancy charges", "technical fee", "technical service", "audit fee", "legal", "legal fees", "legal fee", "advocate", "retainer", "sitting fee", "architect", "designing charges", "software service", "management fee"], "rate": 0.1, "individual_rate": 0.1, "threshold": 50000}, {"section": "194I", "keywords": ["rent", "office rent", "godown rent", "warehouse rent", "factory rent", "shop rent", "lease", "hire charge", "machinery hire", "equipment hire", "plant hire", "vehicle hire"], "rate": 0.1, "individual_rate": 0.1, "threshold": 600000}, {"section": "194H", "keywords": ["commission", "brokerage", "commission expenses", "brokerage charges"], "rate": 0.02, "individual_rate": 0.02, "threshold": 20000}, {"section": "194A", "keywords": ["interest on loan", "interest on unsecured loan", "interest to", "loan interest", "interest paid"], "rate": 0.1, "individual_rate": 0.1, "threshold": 10000}, {"section": "194Q", "keywords": ["purchase", "purchases", "purchase account", "goods purchase", "raw material purchase", "trading purchase"], "rate": 0.001, "individual_rate": 0.001, "threshold": 5000000}]}'::jsonb, '''{account}'' was credited with a base of Rs.{value} during the year on heads that attract TDS, but the tax actually deducted against this party falls short by Rs.{amount} of the {pct}% required at the applicable rate. Please explain WHY tax was not deducted at the prescribed rate — is the payee covered by a lower or nil-deduction certificate u/s 197, is the payee a banking company or other exempt class, is the amount a pure sale of goods outside the section, or is the bill split between material and labour with TDS correctly restricted to the labour component? If deduction was genuinely required, remit the shortfall with interest u/s 201(1A), correct the section and rate in the quarterly return, and quantify the 30% disallowance u/s 40(a)(ia) for Clause 34 of Form 3CD. Where tax HAS been deducted but under a section that does not match the nature of the head — 194C applied to a purchase of goods, or 194C applied to professional or technical fees — reclassify the deduction to the correct section and file a revised return.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- TDS-211: TDS / TCS payable control account standing at a debit (wrong-side) balance
-- measured: 2 findings across 2 engagements (1.0 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('TDS-211', 'TDS / TCS payable control account standing at a debit (wrong-side) balance', 'TDS', 'account',
  '{"check": "expr", "grain": "account", "scope": {"ledger_keywords": ["tds", "t.d.s", "tcs", "t.c.s", "tax deducted at source", "tax collected at source"], "parent_group_keywords": ["duties", "taxes", "payable", "statutory", "current liabilities", "provision"], "nonzero": true}, "where": [{"field": "closing", "op": ">", "value": 25000}, {"field": "parent_group", "op": "not_contains", "value": "receivable"}, {"field": "parent_group", "op": "not_contains", "value": "recievable"}, {"field": "parent_group", "op": "not_contains", "value": "asset"}, {"field": "parent_group", "op": "not_contains", "value": "advance"}, {"field": "parent_group", "op": "not_contains", "value": "deposit"}, {"field": "parent_group", "op": "not_contains", "value": "cash ledger"}, {"field": "ledger", "op": "not_contains", "value": "receivable"}, {"field": "ledger", "op": "not_contains", "value": "recievable"}, {"field": "ledger", "op": "not_contains", "value": "receviable"}, {"field": "ledger", "op": "not_contains", "value": "recoverable"}, {"field": "ledger", "op": "not_contains", "value": "refund"}, {"field": "ledger", "op": "not_contains", "value": "advance"}, {"field": "ledger", "op": "not_contains", "value": "cash ledger"}, {"field": "ledger", "op": "not_contains", "value": "credit ledger"}]}'::jsonb, 'The statutory ledger ''{account}'' is grouped under a payable / duties & taxes head but closes the year with a DEBIT balance of Rs.{amount}. A TDS or TCS payable control account should never stand in debit — the tax collected or deducted can at most be squared off against the challan deposited, never over-deposited into a liability head. Please explain WHY this reversal has arisen: an excess or duplicate challan, a challan deposited under the wrong section, quarter or TAN, interest or late fee debited into the tax ledger instead of a separate head, a deduction entry that was never passed against the payment, or a TDS/TCS receivable ledger that has simply been grouped on the wrong side. Reconcile the ledger challan-wise and section-wise against Form 26AS / the TRACES challan status and the quarterly returns; transfer any interest or late-fee element to a separate non-deductible ''Interest on TDS'' ledger; regroup any genuine excess deposit or receivable to ''Balance with Government Authorities'' under current assets so that statutory liabilities are not shown net of assets; and quantify interest u/s 201(1A) and late fee u/s 234E for Clause 34 reporting in Form 3CD.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- TDS-212: TDS / advance-tax receivable lying stale and unadjusted
-- measured: 30 findings across 7 engagements (4.3 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('TDS-212', 'TDS / advance-tax receivable lying stale and unadjusted', 'TDS', 'account',
  '{"check": "no_movement", "scope": {"ledger_keywords": ["tds", "tcs receivable", "tcs recoverable", "advance tax", "self assessment tax", "income tax refund", "tax refund receivable"], "parent_group_keywords": ["current asset", "loans & advances", "loans and advances", "advance", "deposit", "receivable", "taxes"], "side": "Dr", "nonzero": true}, "min_balance": 50000, "tolerance": 100}'::jsonb, '''{account}'' carries a debit balance of Rs.{amount}, which is exactly where it stood at the start of the year — not one rupee of this tax credit moved during the entire year. Please explain WHY this TDS/advance-tax credit was never adjusted against the income-tax provision of the assessment year it relates to, and was never received as a refund. Specifically confirm (a) whether the credit actually appears against the assessee''s PAN in Form 26AS / AIS for that year, and (b) whether it was allowed in the intimation u/s 143(1). If it was disallowed, or does not appear in 26AS at all, the amount is not recoverable and must be written off to the P&L instead of being carried forward as a fictitious asset. If it is genuinely recoverable, square it off assessment-year-wise against the corresponding tax provision, or give us the refund / rectification / appeal status and the year it pertains to.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();

-- TDS-213: Interest, late fee or penalty on TDS / GST / income tax charged to Profit & Loss
-- measured: 21 findings across 9 engagements (2.3 per engagement)
insert into scrutiny_rules (rule_id, rule_name, category, detection_level, detection_logic,
  audit_query_template, severity, applicable_to, is_active)
values ('TDS-213', 'Interest, late fee or penalty on TDS / GST / income tax charged to Profit & Loss', 'TDS', 'account',
  '{"check": "expr", "grain": "account", "scope": {"ledger_keywords": ["interest on tds", "tds interest", "int on tds", "t.d.s. interest", "t.d.s interest", "interest on tcs", "tcs interest", "interest on gst", "gst interest", "interest on income tax", "income tax interest", "interest on tax", "interest on service tax", "interest & penalty", "interest and penalty", "penal", "penalty on", "fines", "interest on late payment", "interest on late deposit", "interest on delayed payment", "interest on delayed deposit", "late payment interest", "late payment charges", "late fee", "late filing fee", "interest u/s 201", "201(1a)", "234e", "271c", "271h"], "parent_group_keywords": ["expen", "exps", "exp.", "finance cost", "financial charge", "finance exp", "financial exp", "interest and financial", "interest & financial"]}, "where": [{"field": "closing", "op": ">=", "value": 1000}, {"field": "parent_group", "op": "not_contains", "value": "creditor"}, {"field": "parent_group", "op": "not_contains", "value": "payable"}, {"field": "parent_group", "op": "not_contains", "value": "(asset)"}]}'::jsonb, '''{account}'' carries Rs.{amount} debited to the Profit & Loss account, representing interest, late fee or penalty on delayed deduction or delayed deposit of TDS, GST or income tax. Please explain WHY this has been treated as revenue expenditure — interest u/s 201(1A), interest u/s 50 of the CGST Act, late fee u/s 234E and penalties of this nature are penal in character, are not laid out wholly and exclusively for the purposes of business, and are disallowable u/s 37(1) read with s.40(a)(ii). Please provide the section-wise and period-wise computation with the supporting challans, segregate the penalty and late-fee component from any purely compensatory interest, regroup the amount to a separate non-deductible head (or capitalise it to project cost where the entity is still pre-operative), and disclose the disallowance in the computation of total income and in Clause 21(a) of Form 3CD. Also confirm the underlying delay so that the compliance calendar is corrected going forward.', 'medium',
  '["corporate", "non_corporate"]'::jsonb, true)
on conflict (rule_id) do update set
  rule_name = excluded.rule_name, category = excluded.category,
  detection_level = excluded.detection_level, detection_logic = excluded.detection_logic,
  audit_query_template = excluded.audit_query_template, severity = excluded.severity,
  applicable_to = excluded.applicable_to, is_active = true, updated_at = now();